-- NULL retains the existing am/pm/full_day record until its first edit.
alter table public.logistics_board_assignments
  add column placements jsonb,
  add constraint board_placements_valid check (
    placements is null or (
      jsonb_typeof(placements)='array' and
      '[{"slot":"AM","place":"A"},{"slot":"AM","place":"B"},{"slot":"AM","place":"C"},{"slot":"AM","place":"D"},{"slot":"AM","place":"E"},{"slot":"AM","place":"F"},{"slot":"AM","place":"G"},{"slot":"AM","place":"H"},{"slot":"AM","place":"I"},{"slot":"AM","place":"J"},{"slot":"AM","place":"梱包"},{"slot":"AM","place":"パスソート"},{"slot":"AM","place":"配送佐川"},{"slot":"AM","place":"配送南郵便局"},{"slot":"AM","place":"未配置"},{"slot":"AM","place":"休憩 11:30"},{"slot":"AM","place":"休憩 12:00"},{"slot":"AM","place":"休憩 12:30"},{"slot":"AM","place":"応援"},{"slot":"AM","place":"補充"},{"slot":"AM","place":"予備"},{"slot":"AM","place":"欠勤"},{"slot":"ALL","place":"A"},{"slot":"ALL","place":"B"},{"slot":"ALL","place":"C"},{"slot":"ALL","place":"D"},{"slot":"ALL","place":"E"},{"slot":"ALL","place":"F"},{"slot":"ALL","place":"G"},{"slot":"ALL","place":"H"},{"slot":"ALL","place":"I"},{"slot":"ALL","place":"J"},{"slot":"ALL","place":"梱包"},{"slot":"ALL","place":"パスソート"},{"slot":"ALL","place":"配送佐川"},{"slot":"ALL","place":"配送南郵便局"},{"slot":"ALL","place":"未配置"},{"slot":"ALL","place":"休憩 11:30"},{"slot":"ALL","place":"休憩 12:00"},{"slot":"ALL","place":"休憩 12:30"},{"slot":"ALL","place":"応援"},{"slot":"ALL","place":"補充"},{"slot":"ALL","place":"予備"},{"slot":"ALL","place":"欠勤"},{"slot":"PM","place":"A"},{"slot":"PM","place":"B"},{"slot":"PM","place":"C"},{"slot":"PM","place":"D"},{"slot":"PM","place":"E"},{"slot":"PM","place":"F"},{"slot":"PM","place":"G"},{"slot":"PM","place":"H"},{"slot":"PM","place":"I"},{"slot":"PM","place":"J"},{"slot":"PM","place":"梱包"},{"slot":"PM","place":"パスソート"},{"slot":"PM","place":"配送佐川"},{"slot":"PM","place":"配送南郵便局"},{"slot":"PM","place":"未配置"},{"slot":"PM","place":"休憩 11:30"},{"slot":"PM","place":"休憩 12:00"},{"slot":"PM","place":"休憩 12:30"},{"slot":"PM","place":"応援"},{"slot":"PM","place":"補充"},{"slot":"PM","place":"予備"},{"slot":"PM","place":"欠勤"}]'::jsonb @> placements
    )
  );
